from test_clarity import test, tests

test('Every catalog family has verified fallback icon metadata', "for _,def in ipairs(BuffTap.Buffs) do assert(type(def.icon)=='number' and def.icon>0 and def.icon~=134400,def.key) end")
test('Unlearned Paladin spells and group versions display actual icons', "BuffTap.db.friendlyTarget=true; UnitClass=function() return 'Paladin','PALADIN' end; C_Spell.GetSpellTexture=function() return nil end; C_Spell.GetSpellInfo=function() return nil end; BuffTap:Options(); for _,row in ipairs(BuffTap.options.buffRows) do if row.shown then assert(row.icon.texture==row.def.icon); if row.def.groupKey then assert(row.groupIcon.texture==BuffTap:FindBuff(row.def.groupKey).icon) end end end; BuffTap.options.targetBlessingPicks[1].scripts.OnClick(BuffTap.options.targetBlessingPicks[1]); for _,row in ipairs(BuffTap.options.blessingMenu.priorityRows) do assert(row.icon.texture~=134400) end")
test('Placeholder API textures use verified icons across classes without learning spells', "local known=BuffTap.action.id; C_Spell.GetSpellTexture=function() return 134400 end; C_Spell.GetSpellInfo=function() return {iconID=134400} end; for _,class in ipairs({'DRUID','MAGE','PRIEST','PALADIN','SHAMAN','WARLOCK','HUNTER','WARRIOR','ROGUE'}) do UnitClass=function() return class,class end; BuffTap:Options(); for _,row in ipairs(BuffTap.options.buffRows) do if row.shown then assert(row.icon.texture==row.def.icon,row.def.key) end end end; assert(BuffTap.action.id==known and not C_SpellBook.IsSpellKnown(20217))")
print('ALL',len(tests),'SCENARIOS PASSED')
